window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[112]={"id":"112","numero":112,"titre":"Dermatoses bulleuses auto-immunes","objectifs":[{"id":"112-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une dermatose bulleuse auto-immune","contenu":"<div class=\"callout callout-info\">\n        <strong>Cadre nosologique.</strong> Les <span class=\"kw-def\">dermatoses bulleuses auto-immunes (DBAI)</span> forment un\n        <strong>groupe hétérogène de maladies peu fréquentes</strong>, au <span class=\"kw-def\">pronostic</span> variable mais souvent péjoratif.\n        Elles sont caractérisées par la présence d'<span class=\"kw-bio\">auto-anticorps</span> dirigés contre des\n        <span class=\"kw-def\">protéines d'adhérence cutanée</span>, à l'origine de la formation de bulles.\n      </div>\n\n      <h4><span class=\"kw-def\">Physiopathologie</span> — cohésion de la peau</h4>\n      <p>La cohésion de la peau est assurée par <strong>2 systèmes d'adhérence</strong> distincts :</p>\n      <ul>\n        <li><strong>Desmosomes</strong> : assurent la cohésion de l'<span class=\"kw-def\">épiderme</span> (adhérence inter-kératinocytaire)</li>\n        <li><strong>Jonction dermo-épidermique (JDE)</strong> : assure la cohésion entre épiderme et derme. Comprend de la superficie (pôle basal du kératinocyte) vers la profondeur (derme superficiel) :\n          <ul>\n            <li><span class=\"kw-def\">Hémi-desmosomes</span></li>\n            <li><span class=\"kw-def\">Filaments d'ancrage</span></li>\n            <li><span class=\"kw-def\">Lame dense</span></li>\n            <li><span class=\"kw-def\">Fibrilles d'ancrage</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme commun.</strong> Toutes ces structures sont composées de <span class=\"kw-def\">protéines d'adhérence</span>\n        qui peuvent devenir la cible d'<span class=\"kw-bio\">auto-AC</span>, à l'origine du clivage cutané et de la formation de bulles.\n      </div>\n\n      <h4><span class=\"kw-def\">Classification</span> physiopathologique des DBAI</h4>\n      <table >\n        <thead><tr><th>Famille</th><th>Cible des auto-AC</th><th>Conséquence cutanée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>DBAI intra-épidermiques (pemphigus)</strong></td>\n            <td><span class=\"kw-bio\">Auto-AC anti-substance intercellulaire (SIC)</span><br>Cible : <span class=\"kw-def\">desmosomes</span></td>\n            <td><span class=\"kw-def\">Perte de cohésion des kératinocytes</span> = <strong><span class=\"kw-clinique\">acantholyse</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>DBAI sous-épidermiques (pemphigoïdes et autres)</strong></td>\n            <td><span class=\"kw-bio\">Auto-AC anti-membrane basale</span><br>Cible : composant de la <span class=\"kw-def\">JDE</span></td>\n            <td><span class=\"kw-def\">Perte d'adhérence dermo-épidermique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span></em></p>","frequence":0},{"id":"112-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","contenu":"<div class=\"callout callout-info\">\n        <strong>Triptyque diagnostique.</strong> Le diagnostic d'une DBAI repose sur 3 niveaux complémentaires —\n        <span class=\"kw-clinique\">clinique</span>, <span class=\"kw-imagerie\">histologique</span>, <span class=\"kw-bio\">immunopathologique</span>.\n      </div>\n\n      <h4>1. Présentation clinique — dermatose bulleuse</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> élémentaire — bulle</strong></td>\n            <td>\n              <span class=\"kw-def\">Lésion liquidienne superficielle</span> :<br>\n              <strong>Contenu :</strong> clair ou sérohématique<br>\n              <strong><span class=\"kw-clinique\">Diamètre</span> :</strong> <span class=\"kw-chiffre\">&gt; 5 mm</span> <em>(en dessous = <span class=\"kw-clinique\">vésicule</span>)</em><br>\n              <strong>Siège :</strong> peau ou muqueuses\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres lésions évocatrices</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Érosions cutanées post-bulleuses</span> : arrondies, parfois recouvertes d'une <span class=\"kw-clinique\">croûte</span></li>\n                <li><span class=\"kw-clinique\">Érosions des muqueuses externes</span> (bulles muqueuses fugaces et rarement vues)</li>\n                <li><span class=\"kw-clinique\">Vaste décollement épidermique</span> : aspect de « linge mouillé sur la peau »</li>\n                <li><strong>Signe de Nikolsky</strong> = <span class=\"kw-clinique\">décollement cutané provoqué par un frottement appuyé sur peau saine</span> ; traduit un décollement intra-épidermique (<span class=\"kw-def\">acantholyse</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. <span class=\"kw-bio\">Histologie</span> — <span class=\"kw-clinique\">bulle</span> intra ou sous-épidermique</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Prélèvement</strong></td>\n            <td><span class=\"kw-ttt\">Biopsie</span> sous <span class=\"kw-ttt\">anesthésie locale</span> :<br>\n              <strong>Site préférentiel :</strong> <span class=\"kw-clinique\">bulle</span> cutanée intacte et récente<br>\n              <strong>Alternative :</strong> bord d'une <span class=\"kw-clinique\">érosion</span> muqueuse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intra-épidermique</strong></td>\n            <td><span class=\"kw-imagerie\">Bulle par détachement des kératinocytes entre eux</span><br>→ <span class=\"kw-clinique\">bulle flasque et fragile</span> (toit très fin du fait du clivage intra-épidermique)</td>\n          </tr>\n          <tr>\n            <td><strong>Sous-épidermique</strong></td>\n            <td><span class=\"kw-imagerie\">Bulle par clivage entre derme et épiderme</span><br>→ <span class=\"kw-clinique\">bulle tendue</span> (toit constitué par l'épiderme intact)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Immunopathologie — origine <span class=\"kw-etio\">auto-immune</span></h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>IFD (<span class=\"kw-bio\">immunofluorescence</span> directe)</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Biopsie de peau/muqueuse péri-lésionnelle ⚠️</span> (contrairement à l'<span class=\"kw-bio\">histologie</span> qui prend la <span class=\"kw-clinique\">bulle</span>).<br>\n              Met en évidence des dépôts in vivo de <span class=\"kw-bio\">IgG</span> et/ou <span class=\"kw-bio\">IgA</span> et/ou <span class=\"kw-bio\">C3</span> selon 3 patterns :\n              <ul>\n                <li><strong>En résille au pourtour des kératinocytes</strong> → <span class=\"kw-def\">DBAI intra-épidermiques (pemphigus)</span></li>\n                <li><strong>Linéaire le long de la JDE</strong> (ou JCE muqueuse) → <span class=\"kw-def\">DBAI sous-épidermiques</span></li>\n                <li><strong>Granuleux au sommet des papilles dermiques</strong> → <span class=\"kw-def\">dermatite herpétiforme</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen du sérum</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Immunofluorescence indirecte (IFI)</span> : recherche d'<strong>AC anti-membrane basale</strong> ou <strong>AC anti-substance intercellulaire</strong></li>\n                <li><span class=\"kw-bio\">Immunotransfert</span> ou <span class=\"kw-bio\">ELISA</span> : caractérisent les <strong>antigènes reconnus</strong> par les auto-AC</li>\n                <li><strong>Classe d'Ig</strong> à préciser (IgG <span class=\"kw-bio\">vs</span> IgA) pour l'orientation étiologique</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège — Nikolsky n'est PAS spécifique du pemphigus.</strong> Autres causes à connaître :\n        <span class=\"kw-alerte\">nécrolyse épidermique toxique (Stevens-Johnson, Lyell)</span> ;\n        pemphigus ; <span class=\"kw-alerte\">épidermolyse staphylococcique aiguë (SSSS)</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies · 158 — Sepsis et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":3},{"id":"112-3","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir argumenter le diagnostic des différentes maladies bulleuses auto-immunes","contenu":"<div class=\"callout callout-warn\">\n        <strong>Objectif phare de l'item (6⭐ bruts).</strong> Le <span class=\"kw-def\">diagnostic différentiel</span> <span class=\"kw-def\">pemphigus</span> <span class=\"kw-bio\">vs</span>\n        <span class=\"kw-def\">pemphigoïde bulleuse</span> est le QCM-type EDN. La distinction repose sur 4 axes :\n        <strong><span class=\"kw-def\">terrain</span></strong>, <strong>aspect des bulles</strong>, <strong>peau péri-lésionnelle</strong>, <strong>immunopathologie</strong>.\n      </div>\n\n      <h4>A. Tableau comparatif pemphigus <span class=\"kw-bio\">vs</span> pemphigoïde bulleuse</h4>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Pemphigoïde bulleuse</th><th>Pemphigus</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><strong>DBAI <span class=\"kw-etio\">auto-immune</span> la plus fréquente</strong></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Sujet âgé (en moyenne <span class=\"kw-chiffre\">80 ans</span>)</td>\n            <td>Vers <span class=\"kw-chiffre\">40-50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidités</span></strong></td>\n            <td>Maladies neurologiques grabatisantes :<br><strong>Label :</strong> <span class=\"kw-alerte\">AVC</span> ; démence ; maladie de Parkinson</td>\n            <td>MAI associées :<br><strong>Label :</strong> myasthénie ; lupus érythémateux ; Gougerot-Sjögren ; PR ; Basedow ; glomérulonéphrite</td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments inducteurs</strong></td>\n            <td><span class=\"kw-ttt\">Diurétiques épargnant le K+</span></td>\n            <td><strong>Groupe thiol :</strong> <span class=\"kw-ttt\">D-pénicillamine</span> ; <span class=\"kw-ttt\">captopril</span> (<span class=\"kw-ttt\">IEC</span>) ; <span class=\"kw-ttt\">thiopronine</span> ; <span class=\"kw-ttt\">pyrithioxine</span><br><strong>Autres :</strong> <span class=\"kw-ttt\">piroxicam</span> ; <span class=\"kw-ttt\">β-bloquants</span> ; <span class=\"kw-ttt\">phénylbutazone</span> ; <span class=\"kw-ttt\">rifampicine</span></td>\n          </tr>\n          <tr>\n            <td><strong>Bulles</strong></td>\n            <td><span class=\"kw-clinique\">Tendues</span></td>\n            <td><span class=\"kw-clinique\">Flasques, fragiles</span></td>\n          </tr>\n          <tr>\n            <td><strong>Localisations</strong></td>\n            <td><strong>Lésions symétriques :</strong> abdomen ; racine des membres ; face de flexion des membres ; extrémité (forme dyshidrosique)</td>\n            <td><strong>Pemphigus vulgaire :</strong> plis de flexion ; cuir chevelu ; zones de frottement<br><strong>Pemphigus superficiel :</strong> zones séborrhéiques (face antérieure du thorax ; visage ; cuir chevelu ; région interscapulaire)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span></strong></td>\n            <td><span class=\"kw-clinique\">Oui — prurit généralisé intense</span></td>\n            <td><span class=\"kw-clinique\">Non</span> (sauf parfois lésions squamo-croûteuses des pemphigus superficiels)</td>\n          </tr>\n          <tr>\n            <td><strong>Nikolsky</strong></td>\n            <td><span class=\"kw-alerte\">Pas de signe de Nikolsky ❌</span></td>\n            <td><span class=\"kw-clinique\">Oui</span> (pemphigus vulgaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte muqueuse</strong></td>\n            <td><span class=\"kw-clinique\">Rare</span>, souvent absente ❌</td>\n            <td><strong>Présente</strong> dans le pemphigus vulgaire ;<br>absente dans le pemphigus superficiel ❌</td>\n          </tr>\n          <tr>\n            <td><strong>Peau péri-lésionnelle</strong></td>\n            <td><span class=\"kw-clinique\">Placards eczématiformes ou urticariens</span></td>\n            <td><span class=\"kw-clinique\">Peau saine</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">NFS</span></strong></td>\n            <td><span class=\"kw-bio\">Hyperéosinophilie fréquente</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td><span class=\"kw-imagerie\">Bulle sous-épidermique contenant des PNE</span><br><span class=\"kw-imagerie\">Infiltrat dermique riche en PNE</span><br><span class=\"kw-alerte\">Pas d'acantholyse, pas de nécrose ❌</span></td>\n            <td><span class=\"kw-imagerie\">Bulle intra-épidermique</span> :<br><strong>Label :</strong> suprabasale (pemphigus vulgaire) ; sous-cornée (pemphigus superficiel)<br><span class=\"kw-def\">Acantholyse</span> (kératinocytes détachés)</td>\n          </tr>\n          <tr>\n            <td><strong>Immunopathologie</strong></td>\n            <td>\n              <span class=\"kw-bio\">IFD :</span> dépôts linéaires d'IgG et/ou C3 à la JDE<br>\n              <span class=\"kw-bio\">IFI standard :</span> AC anti-membrane basale (IgG) dans <span class=\"kw-chiffre\">80 %</span> des cas<br>\n              → <span class=\"kw-alerte\">Titre non lié à la sévérité ❌</span><br>\n              <span class=\"kw-bio\">Western blot / ELISA :</span> anti-<span class=\"kw-def\">BPAG1 (BP230)</span> et anti-<span class=\"kw-def\">BPAG2 (BP180)</span><br>\n              <span class=\"kw-bio\">IFI sur peau clivée :</span> AC se fixent au toit (versant épidermique)\n            </td>\n            <td>\n              <span class=\"kw-bio\">IFD :</span> dépôts d'IgG et C3 au pourtour des kératinocytes (résille / maille de filet)<br>\n              <span class=\"kw-bio\">IFI standard :</span> AC circulants anti-SIC (IgG, titre <strong>corrélé à l'activité</strong> ✅)<br>\n              <span class=\"kw-bio\">Immunotransfert / ELISA :</span><br>\n              → Pemphigus vulgaire = <span class=\"kw-def\">desmogléine 3</span> (± desmogléine 1)<br>\n              → Pemphigus superficiel = <span class=\"kw-def\">desmogléine 1</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span></strong></td>\n            <td><span class=\"kw-alerte\">Maladie grave</span> — <span class=\"kw-def\">mortalité</span> à<span class=\"kw-chiffre\"> 1 an</span> de <span class=\"kw-chiffre\">30-40 %</span></td>\n            <td><span class=\"kw-alerte\">Mortalité autour de <span class=\"kw-chiffre\">10 %</span></span> (surtout complications iatrogènes)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>B. Orientation clinique devant une DBAI</h4>\n      <table >\n        <thead><tr><th>Élément d'orientation</th><th>Hypothèse étiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Grossesse</span></strong></td>\n            <td><span class=\"kw-clinique\">Pemphigoïde gravidique</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnels/familiaux MAI</strong></td>\n            <td><strong>Label :</strong> maladie cœliaque ↔ <span class=\"kw-def\">dermatite herpétiforme</span> ; MAI variées ↔ <span class=\"kw-def\">pemphigus</span></td>\n          </tr>\n          <tr>\n            <td><strong>Maladies neurologiques grabatisantes</strong></td>\n            <td><span class=\"kw-alerte\">AVC</span>, démence, Parkinson ↔ <span class=\"kw-def\">pemphigoïde bulleuse</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span></strong></td>\n            <td>DBAI sous-épidermiques :<br><strong>Label :</strong> pemphigoïde bulleuse ; <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">herpétiforme</span> ++<br>Parfois lésions squamo-croûteuses des pemphigus superficiels</td>\n          </tr>\n          <tr>\n            <td><strong>Aspect des bulles</strong></td>\n            <td><strong>Label :</strong> flasques → <span class=\"kw-def\">pemphigus</span> ; tendues → DBAI de la <span class=\"kw-def\">JDE</span></td>\n          </tr>\n          <tr>\n            <td><strong>Nikolsky</strong></td>\n            <td><span class=\"kw-clinique\">Pemphigus</span></td>\n          </tr>\n          <tr>\n            <td><strong>Peau péri-bulleuse</strong></td>\n            <td><strong>Urticarienne/érythémateuse :</strong> pemphigoïde bulleuse<br><strong>Saine :</strong> pemphigus, épidermolyse bulleuse <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n          <tr>\n            <td><strong>Topographies</strong></td>\n            <td><strong>Label :</strong> tronc + face de flexion = pemphigoïde bulleuse ; plis de flexion + cuir chevelu = pemphigus vulgaire, pemphigoïde cicatricielle ; faces d'extension = <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">herpétiforme</span>, épidermolyse bulleuse <span class=\"kw-etio\">acquise</span> ; zones séborrhéiques = pemphigus superficiel</td>\n          </tr>\n          <tr>\n            <td><strong>Lésions muqueuses</strong></td>\n            <td>Présence dans :<br><strong>Label :</strong> pemphigus (sauf superficiel) ; pemphigoïde cicatricielle ; épidermolyse bulleuse <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>C. Orientation paraclinique — <span class=\"kw-def\">classification</span> IFD + cibles antigéniques</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Maladie</th><th>Dépôts / Cible antigénique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"6\"><strong>DBAI sous-épidermiques</strong></td>\n            <td><strong>Pemphigoïde bulleuse</strong></td>\n            <td><span class=\"kw-bio\">Dépôts linéaires IgG, C3</span><br>Antigènes : <span class=\"kw-def\">BPAG1, BPAG2</span></td>\n          </tr>\n          <tr>\n            <td>Pemphigoïde gravidique</td>\n            <td>Même aspect IFD ; cible : <span class=\"kw-def\">BPAG2</span></td>\n          </tr>\n          <tr>\n            <td>Pemphigoïde cicatricielle</td>\n            <td>Même aspect IFD ; cible : <span class=\"kw-def\">BPAG2</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">herpétiforme</span></strong></td>\n            <td><span class=\"kw-bio\">Dépôts granulaires IgA</span></td>\n          </tr>\n          <tr>\n            <td><strong>Dermatoses à IgA linéaire</strong></td>\n            <td><span class=\"kw-bio\">Dépôts linéaires IgA</span></td>\n          </tr>\n          <tr>\n            <td><strong>Épidermolyse bulleuse <span class=\"kw-etio\">acquise</span></strong></td>\n            <td><span class=\"kw-bio\">Dépôts linéaires IgG / C3</span><br>Cible : <span class=\"kw-def\">collagène VII</span></td>\n          </tr>\n          <tr>\n            <td rowspan=\"5\"><strong>DBAI intra-épidermiques</strong></td>\n            <td><strong>Pemphigus</strong></td>\n            <td><span class=\"kw-bio\">Dépôts IgG, C3 en mailles</span></td>\n          </tr>\n          <tr>\n            <td>Vulgaire</td>\n            <td>Cible : <span class=\"kw-def\">desmogléine 3</span></td>\n          </tr>\n          <tr>\n            <td>Superficiel</td>\n            <td>Cible : <span class=\"kw-def\">desmogléine 1</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Paranéoplasique</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Médicamenteux</span></td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>D. Topographies lésionnelles synthétiques</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Localisation typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pemphigoïde bulleuse</strong></td><td><span class=\"kw-clinique\">Tronc</span> ; <span class=\"kw-clinique\">racine et face de flexion des membres</span> <em>(tombé en annale)</em></td></tr>\n          <tr><td><strong>Pemphigoïde gravidique</strong></td><td><span class=\"kw-clinique\">Péri-ombilical</span></td></tr>\n          <tr><td><strong>Pemphigoïde cicatricielle</strong></td><td><span class=\"kw-clinique\">Érosion tête-cou</span> ; <span class=\"kw-clinique\">atteinte prédominante des muqueuses</span> (conjonctivite synéchiante)<br><span class=\"kw-clinique\">Plis de flexion, cuir chevelu</span> (comme le pemphigus vulgaire)</td></tr>\n          <tr><td><strong>Pemphigus vulgaire</strong></td><td><span class=\"kw-clinique\">Plis de flexion, cuir chevelu</span></td></tr>\n          <tr><td><strong>Pemphigus <span class=\"kw-clinique\">séborrhéique</span></strong></td><td><span class=\"kw-clinique\">Zones séborrhéiques</span> (forme localisée du pemphigus superficiel)</td></tr>\n          <tr><td><strong>Pemphigus foliacé</strong></td><td>Forme disséminée du pemphigus superficiel</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">herpétiforme</span></strong></td><td><span class=\"kw-clinique\">Faces d'extension des membres</span><br><em>Épaules, fesses, faces d'extension des coudes, derrière les genoux</em></td></tr>\n          <tr><td><strong>Épidermolyse bulleuse <span class=\"kw-etio\">acquise</span></strong></td><td><span class=\"kw-clinique\">Faces d'extension des membres</span><br><em>Zones de frottement</em></td></tr>\n        </tbody>\n      </table>\n\n      <h4>E. Entités plus rares à connaître</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">herpétiforme</span>.</strong> <span class=\"kw-def\">DBAI sous-épidermique sans AC anti-JDE ❌</span> — la <span class=\"kw-def\">physiopathologie</span> repose sur une <span class=\"kw-ci\">hypersensibilité</span> à la <span class=\"kw-def\">gliadine</span> du gluten (comme la maladie cœliaque).\n        <ul>\n          <li><strong><span class=\"kw-def\">Terrain</span> :</strong> <span class=\"kw-clinique\">adolescent</span> ou <span class=\"kw-clinique\">adulte jeune</span> ; maladie cœliaque associée, souvent asymptomatique</li>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">prurit diffus longtemps isolé</span> ; bulles et vésicules symétriques en <strong>bouquet</strong> et en <strong>anneau</strong> ; localisations : épaules, faces d'extension des coudes, fesses, derrière les genoux ; <span class=\"kw-clinique\">poussées</span> parfois provoquées par une prise excessive de gluten</li>\n          <li><strong>Paraclinique :</strong> <span class=\"kw-imagerie\">clivage sous-épidermique + micro-abcès à PNN du derme papillaire</span> ; <span class=\"kw-bio\">IFD = dépôts granuleux d'IgA en mottes au sommet des papilles dermiques</span> ; <span class=\"kw-bio\">AC anti-endomysium + anti-transglutaminase (IgA)</span> ; <strong><span class=\"kw-imagerie\">FOGD</span></strong> avec biopsies multiples de D2 → entéropathie au gluten</li>\n          <li><strong>Traitement :</strong> <span class=\"kw-ttt\">Dapsone</span> (effet spectaculaire sur <span class=\"kw-clinique\">prurit</span>/lésions, pas sur l'entéropathie) ; <span class=\"kw-ttt\">régime sans gluten à vie</span> si atrophie villositaire</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Dermatoses à IgA linéaire</strong> (rang C). Groupe hétérogène avec en commun : <span class=\"kw-bio\">dépôts linéaires d'IgA isolés ou prédominants</span> sur la JDE.\n        <ul>\n          <li><strong>Enfant :</strong> bulles de grande taille + vésicules en groupement arrondi (<span class=\"kw-clinique\">herpétiforme</span>) ; localisations : moitié inférieure du tronc, fesses, périnée, cuisses</li>\n          <li><strong>Adulte :</strong> formes aiguës <span class=\"kw-ttt\">médicamenteuses</span> (<span class=\"kw-ttt\">vancomycine</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>)</li>\n          <li><strong>Traitement :</strong> arrêt du médicament inducteur + <span class=\"kw-ttt\">Dapsone</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Épidermolyse bulleuse <span class=\"kw-etio\">acquise</span></strong> (rang C). Rare ; <span class=\"kw-clinique\">bulles sur zones de frottement et extrémités</span>, peau péri-lésionnelle saine ; bulles laissant <span class=\"kw-clinique\">cicatrices atrophiques</span> et microkystes ; atteinte muqueuse souvent associée.\n        <ul>\n          <li><strong><span class=\"kw-def\">Comorbidité</span> :</strong> <span class=\"kw-alerte\">association à une maladie de Crohn</span> dans <span class=\"kw-chiffre\">25 %</span> des cas</li>\n          <li><strong>Paraclinique :</strong> <span class=\"kw-imagerie\">clivage sous-dermique</span> ; <span class=\"kw-bio\">IFD = dépôts d'IgG et C3</span> ; <span class=\"kw-bio\">ELISA anti-collagène VII</span> nécessaire au diagnostic</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 194 — Lupus - SAPL</em></p>","frequence":6},{"id":"112-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","contenu":"<div class=\"callout callout-warn\">\n        <strong>Piège QCM majeur (⭐⭐⭐⭐⭐).</strong> Les <span class=\"kw-def\">2 biopsies</span> à réaliser devant une dermatose bulleuse\n        <span class=\"kw-alerte\">NE se font PAS au même endroit</span> :\n        <ul>\n          <li><strong><span class=\"kw-ttt\">Biopsie</span> pour <span class=\"kw-bio\">histologie</span></strong> → <span class=\"kw-clinique\">bulle</span> ou bord d'<span class=\"kw-etio\">érosion</span> <strong>lésionnelle</strong></li>\n          <li><strong><span class=\"kw-ttt\">Biopsie</span> pour IFD</strong> → peau / muqueuse <strong>péri-lésionnelle</strong></li>\n        </ul>\n        Erreur classique en QCM EDN — apprendre par cœur cette dissociation.\n      </div>\n\n      <h4>Tableau récapitulatif des biopsies</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Site et finalité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Biopsie</span> pour <span class=\"kw-bio\">histologie</span></strong><br><em>(standard)</em></td>\n            <td>\n              <strong>Site :</strong> <span class=\"kw-imagerie\">bulle cutanée intacte et récente</span><br>\n              <strong>Alternative :</strong> bord d'une <span class=\"kw-clinique\">érosion</span> muqueuse<br>\n              <strong>Finalité :</strong>\n              <ul>\n                <li><span class=\"kw-imagerie\">Niveau du clivage</span> : intra-épidermique (<span class=\"kw-clinique\">acantholyse</span> → pemphigus) <span class=\"kw-bio\">vs</span> sous-épidermique (pemphigoïdes, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">herpétiforme</span>, épidermolyse bulleuse <span class=\"kw-etio\">acquise</span>)</li>\n                <li><span class=\"kw-imagerie\">Contenu inflammatoire</span> : PNE → pemphigoïde bulleuse ; PNN papillaire → <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">herpétiforme</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Biopsie</span> pour IFD</strong><br><em>(indispensable au diagnostic immunopathologique)</em></td>\n            <td>\n              <strong>Site :</strong> <span class=\"kw-alerte\">peau / muqueuse péri-lésionnelle ⚠️</span><br>\n              <span class=\"kw-alerte\">JAMAIS la bulle elle-même</span> (l'immun-complexe y serait détruit par l'inflammation et la <span class=\"kw-clinique\">nécrose</span>)<br>\n              <strong>Finalité :</strong> mettre en évidence les dépôts in vivo d'<span class=\"kw-bio\">IgG / IgA / C3</span> et leur pattern :\n              <ul>\n                <li><span class=\"kw-bio\">Résille au pourtour des kératinocytes</span> → pemphigus</li>\n                <li><span class=\"kw-bio\">Linéaire le long de la JDE</span> → pemphigoïde bulleuse, cicatricielle, gravidique, épidermolyse bulleuse <span class=\"kw-etio\">acquise</span>, dermatose à IgA linéaire</li>\n                <li><span class=\"kw-bio\">Granulaire au sommet des papilles dermiques</span> → <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">herpétiforme</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examens sanguins complémentaires</h4>\n      <ul>\n        <li><span class=\"kw-bio\">IFI standard</span> : recherche d'AC anti-membrane basale ou anti-substance intercellulaire</li>\n        <li><span class=\"kw-bio\">Immunotransfert</span> et <span class=\"kw-bio\">ELISA</span> : caractérisation fine des antigènes cibles\n          (<strong>Label :</strong> BPAG1 / BPAG2 ; desmogléine 1 / 3 ; collagène VII ; transglutaminase)\n        </li>\n        <li><strong>Préciser la classe d'Ig</strong> (IgG <span class=\"kw-bio\">vs</span> IgA) pour l'orientation étiologique</li>\n        <li><span class=\"kw-bio\">NFS</span> : <strong>hyperéosinophilie</strong> fréquente en cas de pemphigoïde bulleuse</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi cette dissociation des sites ?</strong>\n        L'<span class=\"kw-imagerie\">histologie</span> cherche à voir le <strong>clivage et son contenu</strong> → <span class=\"kw-ttt\">biopsie</span> dans la <span class=\"kw-clinique\">lésion</span>.\n        L'<span class=\"kw-bio\">IFD</span> cherche à voir les <strong>dépôts d'Ig fixés in vivo sur la zone d'adhérence</strong> → biopsie dans une peau encore architecturée, non détruite par le décollement.\n      </div>","frequence":5},{"id":"112-5","rang":"B","rubrique":"Étiologies","titre":"Connaître les autres étiologies des maladies bulleuses","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif culture dermato.</strong> Devant une dermatose bulleuse, deux questions à se poser dans l'ordre :\n        (1) est-ce vraiment une <span class=\"kw-clinique\">bulle</span> (<span class=\"kw-bio\">vs</span> vésicule / pustule) ? (2) si bulleuse, est-elle <span class=\"kw-def\">auto-immune</span> ou <span class=\"kw-def\">non auto-immune</span> ?\n      </div>\n\n      <h4>A. <span class=\"kw-def\">Diagnostic différentiel</span> d'une dermatose initialement non bulleuse</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th><span class=\"kw-clinique\">Diamètre</span></th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Bulle</span></strong></td><td><span class=\"kw-chiffre\">&gt; 5 mm</span></td><td>Clair ou sérohématique</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vésicule</span></strong></td><td><span class=\"kw-chiffre\">1-2 mm</span></td><td>Clair ou sérohématique</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Pustule</span></strong></td><td>—</td><td>Purulent</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Attention</strong> — la distinction taille n'est pas absolue :\n        <ul>\n          <li>Certaines DBAI (<span class=\"kw-clinique\">dermatite herpétiforme</span>, pemphigoïdes bulleuses) peuvent s'accompagner de vésicules</li>\n          <li>Inversement, il existe des <span class=\"kw-clinique\">formes bulleuses</span> de dermatoses vésiculeuses :<br><strong>Label :</strong> herpès ; zona ; <span class=\"kw-clinique\">eczéma</span> ; vascularite nécrotico-bulleuse</li>\n        </ul>\n      </div>\n\n      <h4>B. Dermatoses bulleuses non auto-immunes (DBNAI)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle d'exclusion.</strong> Les maladies bulleuses non auto-immunes seront éliminées sur :\n        <strong>aspect clinique</strong> + <strong><span class=\"kw-clinique\">évolution</span></strong> + <span class=\"kw-bio\">négativité des examens immunopathologiques</span>\n        (essentiellement l'<strong>IFD cutanée</strong>).\n      </div>\n\n      <h4>B1. Étiologies tous âges</h4>\n      <table >\n        <thead><tr><th>Cause</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Érythème</span> pigmenté fixe bulleux</strong></td>\n            <td><span class=\"kw-clinique\">Bulles possibles</span> sur <span class=\"kw-clinique\">lésion</span> pigmentée récidivant au même site après prise médicamenteuse</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Syndromes de Stevens-Johnson et de Lyell (NET)</strong></span></td>\n            <td><span class=\"kw-def\">Nécrolyse épidermique toxique</span> — <span class=\"kw-alerte\">toxidermie grave, urgence</span> ; signe de Nikolsky positif ; atteinte muqueuse sévère ; décollement étendu</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Érythème</span> polymorphe majeur / bulleux</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> enfant, adulte jeune<br>\n              <strong>Causes :</strong> survient souvent <span class=\"kw-chiffre\">10-15 jours</span> après une infection (<span class=\"kw-clinique\">récurrence d'herpès</span> ++, plus rarement <span class=\"kw-bio\">Mycoplasma pneumoniae</span>)<br>\n              <strong>Manifestations :</strong>\n              <ul>\n                <li><span class=\"kw-clinique\">Lésions en « cocardes » ou « cibles »</span> : <span class=\"kw-chiffre\">≥ 3</span> cercles concentriques, centre inconstamment vésico-bulleux</li>\n                <li>Localisation <span class=\"kw-clinique\">acrale</span> (coudes, genoux, mains, pieds, <strong>visage</strong>), souvent symétrique</li>\n                <li>Lésions muqueuses bulleuses ou érosives fréquentes (différencie de la forme mineure)</li>\n              </ul>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> guérison spontanée en <span class=\"kw-chiffre\">2-3 semaines</span> ; récidives fréquentes\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Agents externes</strong></td>\n            <td>\n              <strong>Chimiques :</strong> <span class=\"kw-clinique\">dermatite</span> caustique ; piqûre d'insecte<br>\n              <strong>Physiques :</strong> <span class=\"kw-alerte\">brûlures thermiques</span> ; <span class=\"kw-clinique\">érythème actinique</span> (coup de soleil) ; photophytodermatose (« dermite des prés »)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>B2. Étiologies par <span class=\"kw-def\">terrain</span></h4>\n      <table >\n        <thead><tr><th>Terrain</th><th>Entité(s)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>\n              <strong>Porphyrie cutanée tardive</strong> (rang C) :<br>\n              <ul>\n                <li><span class=\"kw-clinique\">Vésicules et bulles des régions découvertes</span> (dos des mains, visage) d'<span class=\"kw-clinique\">évolution</span> cicatricielle</li>\n                <li><span class=\"kw-clinique\">Fragilité cutanée</span></li>\n                <li><span class=\"kw-clinique\">Hyperpigmentation et hyperpilosité temporo-malaire</span></li>\n                <li><span class=\"kw-bio\">Taux élevé d'uroporphyrine urinaire</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>\n              <strong>Épidermolyse bulleuse <span class=\"kw-etio\">héréditaire</span></strong> (rang C) :<br>\n              <ul>\n                <li><span class=\"kw-def\">Génodermatose</span> par mutation de gènes codant les protéines de la JDE → fragilité cutanée anormale</li>\n                <li>Début habituel en <span class=\"kw-clinique\">période néonatale</span></li>\n                <li>Bulles sur zones de friction ou de traumatisme (extrémités, faces d'extension)</li>\n                <li><strong>ATCD familiaux</strong></li>\n                <li>Diagnostic : <span class=\"kw-imagerie\">biopsie cutanée (immunohistochimie + microscopie électronique)</span> + biologie moléculaire</li>\n              </ul>\n              <strong>Scarlatine staphylococcique</strong> = épidermolyse staphylococcique (cf bloc C ci-dessous)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Jamais bulleux ❌</strong></span></td>\n            <td><strong><span class=\"kw-clinique\">Psoriasis</span></strong> n'est jamais bulleux (parfois pustuleux)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>C. Focus — Épidermolyse staphylococcique aiguë (SSSS)</h4>\n      <div class=\"callout callout-danger\">\n        <strong>SSSS — <span class=\"kw-alerte\">urgence</span> vitale pédiatrique.</strong> La forme sévère (<strong>S</strong>taphylococcal <strong>S</strong>calded <strong>S</strong>kin <strong>S</strong>yndrome)\n        engage le <span class=\"kw-alerte\">pronostic vital</span> par <span class=\"kw-alerte\">choc + atteinte multiviscérale</span>. <span class=\"kw-ci\">Corticoïdes contre-indiqués ⚠️</span>.\n      </div>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Agent</strong></td>\n            <td>\n              <span class=\"kw-bio\"><strong>Staphylococcus aureus</strong></span> sécréteur d'<span class=\"kw-def\">entérotoxines</span> (<strong>exfoliatines A et B</strong> ciblant la <span class=\"kw-def\">desmogléine 1</span> → lyse des desmosomes et décollement cutané)<br>\n              ou <span class=\"kw-bio\"><strong>TSST1</strong></span><br>\n              <em>Rappel pédagogique : la desmogléine 1 est aussi la cible des auto-AC dans le pemphigus superficiel.</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <span class=\"kw-clinique\">Enfants <span class=\"kw-chiffre\">&lt; 5 ans</span></span> ++ (nouveau-nés, nourrissons, jeunes enfants) ; adulte immunodéprimé<br>\n              <em>Enfants plus âgés ont <span class=\"kw-etio\">acquis</span> les AC. Touche aussi les insuffisants rénaux (mauvaise élimination des toxines).</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contamination</strong></td>\n            <td>Souvent par contact avec un <span class=\"kw-clinique\">adulte porteur sain</span> (épidémies dans les crèches)</td>\n          </tr>\n          <tr>\n            <td><strong>Incubation</strong></td>\n            <td><span class=\"kw-chiffre\">48 h</span></td>\n          </tr>\n          <tr>\n            <td><strong>Présentation clinique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Pas d'angine ❌</span> ni d'autre atteinte muqueuse</li>\n                <li>Contexte <span class=\"kw-etio\">infectieux</span> : brutal, <span class=\"kw-clinique\">fièvre</span>, foyer originel à S. aureus :<br><strong>Label :</strong> <span class=\"kw-clinique\">impétigo</span> ; omphalite ; otite externe</li>\n                <li><span class=\"kw-clinique\">Éruption</span> en 2 temps :\n                  <ul>\n                    <li>1. <span class=\"kw-clinique\">Exanthème scarlatiniforme</span> débutant aux <strong>grands plis</strong> et aux <strong>régions péri-orificielles</strong> (ombilic ++)</li>\n                    <li>2. <span class=\"kw-clinique\">Évolution</span> vers un <span class=\"kw-clinique\">décollement bulleux très superficiel</span> avec <strong>signe de Nikolsky</strong></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Forme sévère — SSSS</strong></td>\n            <td>\n              <span class=\"kw-def\">Critères cliniques</span> du <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">toxique</span> staphylococcique :\n              <ul>\n                <li><span class=\"kw-alerte\">Fièvre</span></li>\n                <li><span class=\"kw-clinique\">Éruption</span> maculaire diffuse (rash érythémateux) ; formation de bulles à<span class=\"kw-chiffre\"> 24-48 h</span></li>\n                <li>Desquamation cutanée secondaire (<span class=\"kw-chiffre\">3-5 jours</span>, voire tardive à <span class=\"kw-chiffre\">14-21 jours</span>)</li>\n                <li>Atteinte des phanères possible</li>\n                <li><span class=\"kw-alerte\">Hypotension</span></li>\n                <li><span class=\"kw-alerte\">Atteinte multiviscérale :</span><br><strong>Label :</strong> digestive ; musculaire ; rénale ; hépatique ; hématologique ; neurologique</li>\n              </ul>\n              En pratique : tableau peu spécifique débutant par <span class=\"kw-clinique\">diarrhée</span> → <span class=\"kw-clinique\">hypotension</span> → <span class=\"kw-alerte\">choc</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Confirmation</strong></td>\n            <td>Prélèvements bactériologiques sur le foyer <span class=\"kw-etio\">infectieux</span> initial :<br><strong>Label :</strong> <span class=\"kw-bio\">hémocultures</span> ; <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-ttt\">biopsie</span> cutanée</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Hospitalisation</span></li>\n                <li><span class=\"kw-ttt\">Antibiothérapie</span> (bon <span class=\"kw-def\">pronostic</span> sous ATB) : <strong>pénicilline M (oxacilline)</strong> ou <span class=\"kw-ttt\">clindamycine</span> ; <span class=\"kw-ttt\">vancomycine</span> si SARM</li>\n                <li><span class=\"kw-ci\"><strong>Corticoïdes contre-indiqués ⚠️</strong></span></li>\n                <li>Éviction scolaire jusqu'à <span class=\"kw-chiffre\">48 h</span> de traitement</li>\n                <li><span class=\"kw-clinique\">Évolution</span> souvent bénigne, malgré le risque de complications</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies · 158 — Sepsis et <span class=\"kw-alerte\">choc septique</span> · 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>…</em></p>","frequence":0},{"id":"112-6","rang":"A","rubrique":"Contenu multimédia","titre":"Reconnaître une lésion bulleuse","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif sémiologique transversal.</strong> Reconnaître une <span class=\"kw-clinique\">bulle</span> = savoir la <strong>définir</strong>, la <strong>distinguer</strong> des autres lésions élémentaires liquidiennes (<span class=\"kw-clinique\">vésicule</span>, pustule), et identifier les <strong>signes associés</strong> qui orientent vers une DBAI.\n      </div>\n\n      <h4>Définition de la <span class=\"kw-clinique\">bulle</span></h4>\n      <ul>\n        <li><span class=\"kw-def\">Soulèvement liquidien de la peau ou des muqueuses</span></li>\n        <li><strong><span class=\"kw-clinique\">Diamètre</span> :</strong> <span class=\"kw-chiffre\">&gt; 5 mm</span></li>\n        <li><strong>Contenu :</strong> clair ou sérohématique</li>\n        <li><strong>Toit :</strong>\n          <ul>\n            <li><span class=\"kw-clinique\">Tendue</span> = toit ferme → clivage <strong>sous-épidermique</strong> (toit constitué par l'épiderme intact)</li>\n            <li><span class=\"kw-clinique\">Flasque</span> = toit fragile → clivage <strong>intra-épidermique</strong> (toit très fin, kératinocytes détachés)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Lésions évocatrices secondaires</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Érosions post-bulleuses</span> arrondies, parfois croûteuses</li>\n        <li><span class=\"kw-clinique\">Vaste décollement épidermique</span> donnant un aspect de « linge mouillé sur la peau »</li>\n        <li><span class=\"kw-clinique\">Cocardes / cibles</span> à centre vésico-bulleux → <span class=\"kw-clinique\">érythème</span> polymorphe</li>\n      </ul>\n\n      <h4>Signe associé majeur à rechercher</h4>\n      <div class=\"callout callout-warn\">\n        <strong>Signe de Nikolsky.</strong> <span class=\"kw-clinique\">Décollement cutané provoqué par un frottement appuyé sur peau saine</span>.\n        Traduit un <span class=\"kw-def\">décollement intra-épidermique (acantholyse)</span>.<br>\n        <strong>Étiologies à connaître :</strong>\n        <ul>\n          <li><span class=\"kw-def\">Pemphigus</span> (vulgaire ++)</li>\n          <li><span class=\"kw-alerte\">Nécrolyse épidermique toxique</span> (<span class=\"kw-alerte\">Stevens-Johnson</span>, Lyell)</li>\n          <li><span class=\"kw-alerte\">Épidermolyse staphylococcique aiguë (SSSS)</span></li>\n        </ul>\n      </div>\n\n      <h4>Topographies orientantes (aperçu)</h4>\n      <table >\n        <thead><tr><th>Topographie</th><th>Évoquer</th></tr></thead>\n        <tbody>\n          <tr><td>Symétrique tronc + face de flexion des membres</td><td><span class=\"kw-def\">Pemphigoïde bulleuse</span></td></tr>\n          <tr><td>Plis de flexion + cuir chevelu</td><td><span class=\"kw-def\">Pemphigus vulgaire</span></td></tr>\n          <tr><td>Faces d'extension + bouquets (épaules, coudes, fesses, genoux)</td><td><span class=\"kw-def\">Dermatite herpétiforme</span></td></tr>\n          <tr><td>Muqueuses prédominantes (conjonctivite synéchiante)</td><td><span class=\"kw-def\">Pemphigoïde cicatricielle</span></td></tr>\n          <tr><td>Péri-ombilical chez femme enceinte</td><td><span class=\"kw-def\">Pemphigoïde gravidique</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter — iconographie clinique manquante.</strong> Aucune photo de <span class=\"kw-clinique\">bulle</span> de référence n'est disponible\n        dans les fiches sources du dossier <code>112/</code>. Kevin déposera les photos cliniques de référence\n        (bulle tendue type pemphigoïde, bulle flasque type pemphigus, signe de Nikolsky) dans <code>assets/images/112/</code>.\n        <!-- TODO Kevin : déposer bulle-tendue.png, bulle-flasque.png, nikolsky.png dans assets/images/112/ -->\n      </div>","frequence":0},{"id":"112-7","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une pemphigoïde bulleuse","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif iconographique fortement tombable (⭐⭐⭐⭐).</strong> Savoir reconnaître la\n        <span class=\"kw-def\">pemphigoïde bulleuse</span> sur une photo clinique = identifier 4 critères sémiologiques :\n        <strong>bulles tendues</strong>, <strong>peau péri-lésionnelle urticarienne</strong>, <strong>distribution symétrique</strong>, <strong><span class=\"kw-def\">terrain</span> sujet âgé</strong>.\n      </div>\n\n      <h4>Sémiologie clinique de la pemphigoïde bulleuse</h4>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Bulles tendues</strong></span> à contenu clair ou sérohématique</li>\n        <li><span class=\"kw-clinique\">Peau péri-lésionnelle érythémateuse / urticarienne / eczématiforme</span> — placards inflammatoires en regard</li>\n        <li>Distribution <span class=\"kw-clinique\"><strong>symétrique</strong></span> :\n          <ul>\n            <li>Abdomen</li>\n            <li>Racine et face de flexion des membres (cuisses internes, plis du coude, plis poplités)</li>\n            <li>Parfois forme dyshidrosique sur les extrémités</li>\n          </ul>\n        </li>\n        <li><span class=\"kw-alerte\">Pas de signe de Nikolsky ❌</span></li>\n        <li><span class=\"kw-clinique\">Atteinte muqueuse rare / absente</span></li>\n        <li><span class=\"kw-clinique\"><strong>Prurit généralisé intense quasi-constant</strong></span> (peut précéder les bulles)</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Terrain</span> à connaître</h4>\n      <ul>\n        <li>Sujet âgé (en moyenne <span class=\"kw-chiffre\">80 ans</span>)</li>\n        <li><span class=\"kw-def\">Comorbidités</span> neurologiques grabatisantes fréquentes :<br><strong>Label :</strong> <span class=\"kw-alerte\">AVC</span> ; démence ; maladie de Parkinson</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter — photo clinique manquante.</strong> Aucune photographie de pemphigoïde bulleuse\n        n'est disponible dans les fiches sources du dossier <code>112/</code>. Kevin déposera la photo clinique de référence\n        (cliché collège ++ ou cas clinique EDN — bulles tendues sur <span class=\"kw-clinique\">placard</span> urticarien des membres inférieurs)\n        dans <code>assets/images/112/</code>.\n        <!-- TODO Kevin : déposer pemphigoide-bulleuse.png dans assets/images/112/ -->\n      </div>","frequence":4},{"id":"112-8","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie de lésions cutanéo-muqueuses de pemphigus vulgaire","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif iconographique.</strong> Savoir reconnaître le <span class=\"kw-def\">pemphigus vulgaire</span>\n        sur photo clinique = identifier les 4 critères sémiologiques opposés à la pemphigoïde :\n        <strong>bulles flasques</strong>, <strong>peau péri-lésionnelle saine</strong>, <strong>Nikolsky positif</strong>, <strong>atteinte muqueuse souvent inaugurale</strong>.\n      </div>\n\n      <h4>Lésions cutanées du pemphigus vulgaire</h4>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Bulles flasques et fragiles</strong></span> (toit fin par clivage <span class=\"kw-imagerie\">suprabasal intra-épidermique</span>)</li>\n        <li><span class=\"kw-clinique\">Peau péri-lésionnelle saine</span> (sans <span class=\"kw-clinique\">placard</span> urticarien — différence majeure avec la pemphigoïde)</li>\n        <li><span class=\"kw-clinique\"><strong>Signe de Nikolsky positif</strong> ✅</span> (frottement appuyé sur peau saine → décollement = <span class=\"kw-clinique\">acantholyse</span>)</li>\n        <li>Topographies cutanées :\n          <ul>\n            <li><span class=\"kw-clinique\"><strong>Plis de flexion</strong></span> (aisselles, plis inguinaux)</li>\n            <li><span class=\"kw-clinique\"><strong>Cuir chevelu</strong></span></li>\n            <li>Zones de frottement</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Lésions muqueuses du pemphigus vulgaire</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Atteinte muqueuse fréquente</span> :<br><strong>Label :</strong> érosions buccales douloureuses (gencives, palais, langue, lèvres) ; érosions génitales ; érosions conjonctivales</li>\n        <li>Les bulles muqueuses sont <span class=\"kw-clinique\">fugaces et rarement vues</span> — on observe surtout les <strong>érosions post-bulleuses</strong></li>\n        <li><span class=\"kw-clinique\"><strong>Première manifestation</strong> souvent</span> = atteinte buccale isolée pendant des semaines / mois → <span class=\"kw-alerte\">retard diagnostique fréquent ⚠️</span></li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Terrain</span> à connaître</h4>\n      <ul>\n        <li>Adulte <span class=\"kw-chiffre\">40-50 ans</span></li>\n        <li>Association possible à d'autres MAI :<br><strong>Label :</strong> myasthénie ; lupus érythémateux ; Gougerot-Sjögren ; PR ; Basedow ; glomérulonéphrite</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter — photos cliniques manquantes.</strong> Aucune photographie de pemphigus vulgaire\n        n'est disponible dans les fiches sources du dossier <code>112/</code>. Kevin déposera les photos cliniques\n        de référence (érosions buccales du pemphigus vulgaire ++ ; bulles flasques cutanées avec érosions)\n        dans <code>assets/images/112/</code>.\n        <!-- TODO Kevin : déposer pemphigus-vulgaire-muqueux.png et pemphigus-vulgaire-cutane.png dans assets/images/112/ -->\n      </div>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><strong>Pemphigus vulgaire :</strong> érosions buccales <span class=\"kw-clinique\">douloureuses</span> et <span class=\"kw-clinique\">traînantes</span> gênant l'alimentation → <span class=\"kw-alerte\">dysphagie</span> et <span class=\"kw-alerte\">amaigrissement</span></li><li><strong>Pemphigus superficiel :</strong> forme sévère = <span class=\"kw-alerte\">érythrodermie squameuse</span></li><li><strong>Pemphigoïde bulleuse :</strong> <span class=\"kw-alerte\">maladie grave</span>, <span class=\"kw-chiffre\">mortalité 30-40 % à 1 an</span> — décès par complications <span class=\"kw-etio\">infectieuses</span> (septicémies, pneumopathies) et <span class=\"kw-etio\">cardiovasculaires</span> (<span class=\"kw-ci\">insuffisance cardiaque</span>, <span class=\"kw-alerte\">AVC</span>)</li><li><strong>Pemphigoïde cicatricielle :</strong> conjonctivite synéchiante avec <span class=\"kw-alerte\">risque de cécité</span></li><li><strong>Décollement étendu :</strong> vaste décollement épidermique (« <span class=\"kw-clinique\">linge mouillé sur la peau</span> ») → <span class=\"kw-alerte\">pertes hydro-électrolytiques et protéiques</span></li></ul>","principes":"<p>Traitement guidé par le <span class=\"kw-etio\">type de DBAI</span> : il repose sur la <span class=\"kw-ttt\">corticothérapie</span> (locale ou générale) ± <span class=\"kw-ttt\">immunosuppresseurs</span>, avec les mesures adjuvantes de toute <span class=\"kw-ttt\">corticothérapie</span> prolongée.</p><p><strong>Pemphigus</strong></p><p><span class=\"kw-ttt\">Réduction</span> progressive des doses après contrôle (souvent sur plusieurs années)</p><ul><li>Traitement d'attaque : <span class=\"kw-ttt\">corticothérapie générale forte dose</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">1-1,5 mg/kg/j</span>) jusqu'au contrôle de la maladie</li><li><span class=\"kw-ttt\">Rituximab</span> possible en <span class=\"kw-chiffre\">1ʳᵉ intention</span> pour réduire la dose et la durée de la <span class=\"kw-ttt\">corticothérapie</span></li><li><span class=\"kw-ttt\">Immunosuppresseurs</span> (<span class=\"kw-ttt\">azathioprine</span>, cyclophosphamide, <span class=\"kw-ttt\">ciclosporine</span>) en cas de <span class=\"kw-etio\">résistance</span> aux <span class=\"kw-ttt\">corticoïdes</span></li><li>Pemphigus superficiel peu étendu : <span class=\"kw-ttt\">dermocorticoïdes</span> et <span class=\"kw-ttt\">dapsone</span> possibles (alternatives)</li></ul><p><strong>Pemphigoïde bulleuse</strong></p><ul><li><span class=\"kw-chiffre\">1ʳᵉ intention</span> : <span class=\"kw-ttt\">corticothérapie locale forte</span> (<span class=\"kw-ttt\">propionate de clobétasol</span> <span class=\"kw-chiffre\">20-40 g/j</span> sur <span class=\"kw-chiffre\">6-12 mois</span>) — efficacité similaire, meilleure tolérance, baisse de la <span class=\"kw-def\">mortalité</span></li><li><span class=\"kw-ttt\">Corticothérapie générale</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">0,5-0,75 mg/kg/j</span>) possible si atteinte limitée (<span class=\"kw-chiffre\">< 10 bulles/j</span>)</li><li>Mesures générales : <span class=\"kw-ttt\">bains antiseptiques</span>, hydratation (privilégier <span class=\"kw-ttt\">per os</span>), <span class=\"kw-ttt\">nutrition hypercalorique</span></li><li><span class=\"kw-ttt\">Immunosuppresseurs</span> (<span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">mycophénolate</span> mofétil) si résistance ou rechutes multiples</li></ul><p><strong>Formes traitées par dapsone</strong></p><ul><li>Dermatite herpétiforme : <span class=\"kw-ttt\">dapsone</span> (effet spectaculaire sur prurit et lésions) + <span class=\"kw-ttt\">régime sans gluten</span> à vie si <span class=\"kw-etio\">atrophie villositaire</span></li><li>Dermatose à IgA linéaire : <span class=\"kw-ttt\">arrêt du médicament inducteur</span> (<span class=\"kw-ttt\">vancomycine</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>) + <span class=\"kw-ttt\">dapsone</span></li><li>Pemphigoïde cicatricielle : <span class=\"kw-ttt\">dapsone</span> ; si atteinte oculaire évolutive → <span class=\"kw-ttt\">cyclophosphamide</span> ± <span class=\"kw-ttt\">corticothérapie générale</span>, ou <span class=\"kw-ttt\">rituximab</span></li></ul>","suivi":"<p><span class=\"kw-def\">Surveillance</span> surtout <span class=\"kw-clinique\">clinique</span> : <span class=\"kw-clinique\">décompte quotidien du nombre de bulles</span>, <span class=\"kw-clinique\">cicatrisation des érosions</span>, disparition du <span class=\"kw-clinique\">prurit</span> et des lésions eczématiformes ou urticariennes.<br><strong>Pemphigus :</strong> décroissance progressive de la <span class=\"kw-ttt\">corticothérapie</span> sur <span class=\"kw-chiffre\">plusieurs années</span> ; le <span class=\"kw-bio\">titre de l'IFI</span> (AC anti-substance intercellulaire) est corrélé à l'activité de la maladie.<br><strong>Adjuvants :</strong> mesures associées à toute <span class=\"kw-ttt\">corticothérapie</span> prolongée.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dermatose bulleuse — suspicion de DBAI — Bulle > 5 mm, contenu clair ou sérohématique, sur peau ou muqueuse","detail":"<h4>CAT — Démarche diagnostique devant une dermatose bulleuse <span class=\"kw-etio\">auto-immune</span> — De la <span class=\"kw-clinique\">bulle</span> au type de DBAI : <span class=\"kw-bio\">histologie</span> (clivage) → IFD → IFI/ELISA → traitement adapté</h4>","branches":[{"to":"q-clivage","label":"Biopsie (histologie + IFD)","color":"blue"}]},{"id":"q-clivage","kind":"decision","label":"Biopsie : niveau du clivage à l'histologie ? — Histologie sur bulle intacte récente + IFD en peau péri-lésionnelle","branches":[{"to":"q-pemphigus","label":"Intra-épidermique + acantholyse (bulle flasque)","color":"amber"},{"to":"q-ifd-sous","label":"Sous-épidermique, pas d'acantholyse (bulle tendue)","color":"blue"}]},{"id":"q-pemphigus","kind":"decision","label":"Pemphigus — cible antigénique (IFI / ELISA) ? — IFD : dépôts IgG/C3 en mailles de filet (péri-kératinocytaire)","branches":[{"to":"t-pemphigus-vulgaire","label":"Desmogléine 3 · atteinte muqueuse · Nikolsky +","color":"amber"},{"to":"t-pemphigus-superficiel","label":"Desmogléine 1 · zones séborrhéiques · pas de muqueuse","color":"green"}]},{"id":"t-pemphigus-vulgaire","kind":"terminal","label":"Pemphigus vulgaire — Clivage suprabasal · cible desmogléine 3","color":"amber","detail":"<h4>Clinique</h4><ul><li>Lésions muqueuses <span class=\"kw-clinique\">érosives buccales</span> douloureuses et traînantes (souvent révélatrices)</li><li>Bulles <span class=\"kw-clinique\">flasques et fragiles</span> en <span class=\"kw-clinique\">peau saine</span> (plis de flexion, cuir chevelu)</li><li><span class=\"kw-clinique\">Signe de Nikolsky</span> positif</li></ul><h4>Paraclinique</h4><ul><li>Histo : <span class=\"kw-bio\">acantholyse</span>, clivage <span class=\"kw-bio\">suprabasal</span></li><li>IFD : dépôts d'<span class=\"kw-bio\">IgG et C3</span> en mailles de filet</li><li>IFI : <span class=\"kw-bio\">AC anti-substance intercellulaire</span> (titre corrélé à l'activité) ; ELISA : <span class=\"kw-bio\">desmogléine 3</span> ± 1</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie générale forte dose</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">1-1,5 mg/kg/j</span>) en traitement d'attaque</li><li><span class=\"kw-ttt\">Rituximab</span> possible en 1ʳᵉ intention ; <span class=\"kw-ttt\">immunosuppresseurs</span> si résistance</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Décroissance sur <span class=\"kw-chiffre\">plusieurs années</span>, <span class=\"kw-bio\">titre IFI</span> suivant l'activité</li><li><span class=\"kw-chiffre\">Mortalité ~10 %</span>, surtout par complications iatrogènes</li></ul>"},{"id":"t-pemphigus-superficiel","kind":"terminal","label":"Pemphigus superficiel (séborrhéique / foliacé) — Clivage sous-corné · cible desmogléine 1","color":"green","detail":"<h4>Clinique</h4><ul><li>Bulles fugaces remplacées par des <span class=\"kw-clinique\">lésions squamo-croûteuses</span> des <span class=\"kw-clinique\">zones séborrhéiques</span></li><li><span class=\"kw-clinique\">Pas d'atteinte muqueuse</span> ; forme sévère = <span class=\"kw-alerte\">érythrodermie squameuse</span></li></ul><h4>Paraclinique</h4><ul><li>IFD en mailles (<span class=\"kw-bio\">IgG/C3</span>) ; ELISA : <span class=\"kw-bio\">desmogléine 1</span></li></ul><h4>Traitement</h4><ul><li>Forme peu étendue : <span class=\"kw-ttt\">dermocorticoïdes</span> et <span class=\"kw-ttt\">dapsone</span> possibles</li><li>Sinon <span class=\"kw-ttt\">corticothérapie générale</span></li></ul>"},{"id":"q-ifd-sous","kind":"decision","label":"DBAI sous-épidermique — aspect des dépôts en IFD ? — Bulle tendue, pas d'acantholyse","branches":[{"to":"t-pemphigoide-bulleuse","label":"Linéaire IgG/C3 à la JDE · sujet âgé · prurit","color":"red"},{"to":"t-dermatite-herpetiforme","label":"Granuleux IgA au sommet des papilles","color":"blue"},{"to":"t-iga-lineaire","label":"Linéaire IgA","color":"blue"}]},{"id":"t-pemphigoide-bulleuse","kind":"terminal","label":"Pemphigoïde bulleuse — DBAI la plus fréquente · sujet âgé (~80 ans)","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Prurit généralisé intense</span> + placards eczématiformes ou urticariens</li><li><span class=\"kw-clinique\">Bulles tendues</span> de grande taille, symétriques (abdomen, racine et face de flexion des membres)</li><li><span class=\"kw-clinique\">Pas de signe de Nikolsky</span>, atteinte muqueuse rare</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span> : <span class=\"kw-bio\">hyperéosinophilie</span> fréquente</li><li>Histo : <span class=\"kw-clinique\">bulle</span> sous-épidermique riche en <span class=\"kw-bio\">PNE</span>, pas d'<span class=\"kw-clinique\">acantholyse</span></li><li>IFD : dépôts <span class=\"kw-bio\">linéaires IgG/C3</span> à la JDE ; ELISA : <span class=\"kw-bio\">anti-BPAG1 et BPAG2</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-chiffre\">1ʳᵉ intention</span> : <span class=\"kw-ttt\">clobétasol</span> local (<span class=\"kw-chiffre\">20-40 g/j</span>) — efficacité similaire, meilleure tolérance</li><li>Mesures générales : <span class=\"kw-ttt\">bains antiseptiques</span>, hydratation per os, <span class=\"kw-ttt\">nutrition hypercalorique</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Décompte quotidien des bulles</span>, cicatrisation, disparition du <span class=\"kw-clinique\">prurit</span></li><li><span class=\"kw-alerte\">Maladie grave</span> : <span class=\"kw-chiffre\">mortalité 30-40 % à 1 an</span> (complications infectieuses et cardiovasculaires)</li></ul>"},{"id":"t-dermatite-herpetiforme","kind":"terminal","label":"Dermatite herpétiforme — Hypersensibilité au gluten (maladie cœliaque associée)","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Prurit diffus</span>, bulles/vésicules en <span class=\"kw-clinique\">bouquet et en anneau</span></li><li>Faces d'extension (coudes, fesses, derrière les genoux) ; poussées provoquées par le gluten</li></ul><h4>Paraclinique</h4><ul><li>IFD : dépôts <span class=\"kw-bio\">granuleux d'IgA</span> au sommet des papilles dermiques</li><li><span class=\"kw-bio\">AC anti-endomysium et anti-transglutaminase</span> ; <span class=\"kw-bio\">FOGD + biopsies de D2</span> (atrophie villositaire)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dapsone</span> (effet spectaculaire) ; <span class=\"kw-ttt\">régime sans gluten</span> si <span class=\"kw-etio\">atrophie villositaire</span></li></ul>"},{"id":"t-iga-lineaire","kind":"terminal","label":"Dermatose à IgA linéaire — Dépôts linéaires d'IgA · souvent médicamenteuse chez l'adulte","color":"blue","detail":"<h4>Clinique</h4><ul><li>Bulles + vésicules en groupement <span class=\"kw-clinique\">arrondi (herpétiforme)</span></li><li>Adulte : formes aiguës induites par médicaments (<span class=\"kw-etio\">vancomycine, AINS, IEC</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament inducteur</span> + <span class=\"kw-ttt\">dapsone</span></li></ul>"}]},"cards":[{"i":"0d9aabcaa9f5","n":112,"o":"112-1","u":"Définition","t":"Connaître la définition d’une dermatose bulleuse auto-immune","q":"Quelle est la définition générale d'une dermatose bulleuse auto-immune (DBAI) ?","a":"<p>Les dermatoses bulleuses auto-immunes sont un groupe de maladies <strong>hétérogènes</strong> et <strong>peu fréquentes</strong>, caractérisées par la présence d'<strong>auto-anticorps</strong> dirigés contre des protéines d'adhérence cutanée, responsables de la formation de bulles.</p>"},{"i":"1b60fd5df450","n":112,"o":"112-1","u":"Définition","t":"Connaître la définition d’une dermatose bulleuse auto-immune","q":"Quel est le mécanisme physiopathologique commun à toutes les dermatoses bulleuses auto-immunes (DBAI) ?","a":"<p>Le mécanisme commun implique la production d'<strong>auto-anticorps</strong> qui ciblent les protéines d'adhérence au sein des structures cutanées telles que les desmosomes et la jonction dermo-épidermique. Cette attaque entraîne un <strong>clivage cutané</strong> et la formation de <strong>bulles</strong>.</p>"},{"i":"50bb16aee62c","n":112,"o":"112-1","u":"Définition","t":"Connaître la définition d’une dermatose bulleuse auto-immune","q":"Comment la cohésion de la peau est-elle assurée physiologiquement, et quelles structures sont impliquées dans le mécanisme des dermatoses bulleuses auto-immunes ?","a":"<ul><li>La cohésion de l'épiderme est assurée par les <strong>desmosomes</strong> (adhérence inter-kératinocytaire).</li><li>La cohésion entre épiderme et derme est assurée par la <strong>jonction dermo-épidermique (JDE)</strong>, qui comprend notamment les hémi-desmosomes, les filaments d'ancrage, la lame dense et les fibrilles d'ancrage.</li></ul><p>Les <strong>desmosomes</strong> et les composants de la <strong>JDE</strong> sont les cibles des auto-anticorps dans les DBAI.</p>"},{"i":"8116f6a14e26","n":112,"o":"112-1","u":"Définition","t":"Connaître la définition d’une dermatose bulleuse auto-immune","q":"Quelle est la classification physiopathologique des dermatoses bulleuses auto-immunes selon la localisation du clivage bulleux ?","a":"<ul><li>Les <strong>DBAI intra-épidermiques (pemphigus)</strong> sont caractérisées par des auto-anticorps dirigés contre la substance intercellulaire (desmosomes), entraînant une <strong>acantholyse</strong> (perte de cohésion des kératinocytes).</li><li>Les <strong>DBAI sous-épidermiques (pemphigoïdes et autres)</strong> sont caractérisées par des auto-anticorps dirigés contre la membrane basale (composants de la jonction dermo-épidermique), entraînant une <strong>perte d'adhérence dermo-épidermique</strong>.</li></ul>"},{"i":"03080c621ca6","n":112,"o":"112-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","q":"Dans quelles situations peut-on retrouver un signe de Nikolsky positif, en dehors du pemphigus ?","a":"<p>Le signe de Nikolsky n'est pas spécifique du pemphigus. Il peut être également positif dans les cas suivants :</p><ul><li>La <strong>nécrolyse épidermique toxique</strong> (syndrome de Stevens-Johnson et syndrome de Lyell).</li><li>L'<strong>épidermolyse staphylococcique aiguë (SSSS)</strong>.</li></ul>"},{"i":"18b93f8cf60c","n":112,"o":"112-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","q":"Quels sont les examens immunopathologiques utilisés pour le diagnostic des dermatoses bulleuses auto-immunes ?","a":"<p>Les examens immunopathologiques clés sont :</p><ul><li>L'<strong>immunofluorescence directe (IFD)</strong> sur biopsie de peau/muqueuse <strong>péri-lésionnelle</strong>, recherchant des dépôts in vivo d'IgG, IgA ou C3, avec des patterns spécifiques (en résille, linéaire le long de la JDE, ou granuleux au sommet des papilles dermiques).</li><li>L'<strong>immunofluorescence indirecte (IFI)</strong> sur sérum, recherchant des auto-anticorps circulants anti-membrane basale ou anti-substance intercellulaire.</li><li>L'<strong>immunotransfert</strong> ou <strong>ELISA</strong>, pour caractériser spécifiquement les antigènes reconnus par les auto-anticorps et préciser la classe d'Ig (IgG vs IgA).</li></ul>"},{"i":"91da761e34d4","n":112,"o":"112-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","q":"Comment l'histologie permet-elle de classifier les dermatoses bulleuses auto-immunes ?","a":"<p>L'histologie, réalisée sur une biopsie de bulle cutanée intacte et récente (ou bord d'érosion muqueuse), classe les DBAI selon le siège du clivage :</p><ul><li><strong>Bulle intra-épidermique</strong> : par détachement des kératinocytes entre eux (acantholyse), donnant une bulle flasque et fragile.</li><li><strong>Bulle sous-épidermique</strong> : par clivage entre derme et épiderme, donnant une bulle tendue.</li></ul>"},{"i":"cbcde7fe0108","n":112,"o":"112-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","q":"Quels sont les signes cliniques évocateurs d'une dermatose bulleuse auto-immune ?","a":"<p>Les signes cliniques incluent :</p><ul><li>La <strong>bulle cutanée</strong>, lésion liquidienne superficielle, de contenu clair ou sérohématique, de diamètre supérieur à 5 mm, sur peau ou muqueuses.</li><li>Des <strong>érosions cutanées post-bulleuses</strong>, arrondies, parfois croûteuses.</li><li>Des <strong>érosions des muqueuses externes</strong> (les bulles muqueuses étant fugaces).</li><li>Un <strong>vaste décollement épidermique</strong>, d'aspect de « linge mouillé sur la peau ».</li><li>Le <strong>signe de Nikolsky</strong>, décollement cutané provoqué par un frottement appuyé sur peau saine, traduisant un décollement intra-épidermique (acantholyse).</li></ul>"},{"i":"e6f27e46cc55","n":112,"o":"112-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatose bulleuse auto-immune","q":"Quel est le triptyque diagnostique des dermatoses bulleuses auto-immunes (DBAI) ?","a":"<p>Le diagnostic des DBAI repose sur trois niveaux complémentaires :</p><ul><li>La <strong>présentation clinique</strong>.</li><li>L'<strong>histologie</strong>.</li><li>L'<strong>immunopathologie</strong>.</li></ul>"},{"i":"3d6f096ed01e","n":112,"o":"112-4","u":"Examens complémentaires","t":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","q":"Où doit être réalisée la biopsie cutanée pour immunofluorescence directe (IFD) dans le cadre d'une dermatose bulleuse ?","a":"<p>La biopsie pour IFD doit être réalisée sur une zone de <strong>peau ou muqueuse péri-lésionnelle saine</strong>. Il ne faut <strong>jamais biopsier la bulle elle-même</strong>, car les immunocomplexes y seraient détruits par l'inflammation et la nécrose.</p>"},{"i":"504f3f4e8ec2","n":112,"o":"112-4","u":"Examens complémentaires","t":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","q":"Quelle est la finalité principale de la biopsie cutanée pour histologie dans le diagnostic des dermatoses bulleuses ?","a":"<p>La finalité de la biopsie pour histologie est de déterminer le <strong>niveau du clivage</strong> (intra-épidermique comme dans le pemphigus, ou sous-épidermique comme dans les pemphigoïdes) et d'analyser le <strong>contenu inflammatoire</strong> (par exemple, des polynucléaires éosinophiles pour la pemphigoïde bulleuse ou des polynucléaires neutrophiles papillaires pour la dermatite herpétiforme).</p>"},{"i":"8c7a0d8e03dd","n":112,"o":"112-4","u":"Examens complémentaires","t":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","q":"Quels examens sanguins complémentaires sont utiles pour affiner le diagnostic des dermatoses bulleuses auto-immunes, au-delà de l'histologie et l'IFD ?","a":"<ul><li>Une <strong>immunofluorescence indirecte (IFI) standard</strong> pour rechercher des anticorps anti-membrane basale ou anti-substance intercellulaire.</li><li>Des techniques d'<strong>immunotransfert et ELISA</strong> pour la caractérisation fine des antigènes cibles (par exemple, BPAG1/BPAG2, desmogléines 1/3, collagène VII) et la classe d'immunoglobulines (IgG vs IgA).</li><li>Une <strong>numération formule sanguine (NFS)</strong>, car une hyperéosinophilie est fréquente en cas de pemphigoïde bulleuse.</li></ul>"},{"i":"ea2c80604893","n":112,"o":"112-4","u":"Examens complémentaires","t":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","q":"Quelle est la finalité principale de la biopsie cutanée pour immunofluorescence directe (IFD) dans le diagnostic des dermatoses bulleuses ?","a":"<p>La finalité de l'IFD est de mettre en évidence les <strong>dépôts in vivo d'IgG, d'IgA ou de C3</strong> et d'analyser leur <strong>pattern caractéristique</strong> (par exemple, en résille pour le pemphigus, linéaire le long de la jonction dermo-épidermique pour les pemphigoïdes, ou granulaire au sommet des papilles dermiques pour la dermatite herpétiforme).</p>"},{"i":"ebd11db438a6","n":112,"o":"112-4","u":"Examens complémentaires","t":"Connaître l’intérêt de la biopsie devant une dermatose bulleuse","q":"Où doit être réalisée la biopsie cutanée pour histologie dans le cadre d'une dermatose bulleuse ?","a":"<p>La biopsie pour histologie doit être réalisée sur une <strong>bulle cutanée intacte et récente</strong>. Une alternative est le <strong>bord d'une érosion muqueuse</strong>.</p>"},{"i":"49dbabf7b5f1","n":112,"o":"112-6","u":"Contenu multimédia","t":"Reconnaître une lésion bulleuse","q":"Quelles sont les deux formes morphologiques principales d'une bulle et que traduisent-elles du point de vue histologique ?","a":"<ul><li>Une bulle peut être <strong>tendue</strong> (toit ferme), traduisant un <strong>clivage sous-épidermique</strong> (le toit est constitué par l'épiderme intact).</li><li>Une bulle peut être <strong>flasque</strong> (toit fragile), traduisant un <strong>clivage intra-épidermique</strong> (le toit est très fin, fait de kératinocytes détachés).</li></ul>"},{"i":"9101d3d3e3c1","n":112,"o":"112-6","u":"Contenu multimédia","t":"Reconnaître une lésion bulleuse","q":"Quelles localisations corporelles (topographies) peuvent orienter vers des dermatoses bulleuses spécifiques ?","a":"<ul><li><strong>Symétrique tronc + face de flexion des membres</strong> : Pemphigoïde bulleuse.</li><li><strong>Plis de flexion + cuir chevelu</strong> : Pemphigus vulgaire.</li><li><strong>Faces d'extension + bouquets (épaules, coudes, fesses, genoux)</strong> : Dermatite herpétiforme.</li><li><strong>Muqueuses prédominantes (conjonctivite synéchiante)</strong> : Pemphigoïde cicatricielle.</li><li><strong>Péri-ombilical chez la femme enceinte</strong> : Pemphigoïde gravidique.</li></ul>"},{"i":"92a342b82eda","n":112,"o":"112-6","u":"Contenu multimédia","t":"Reconnaître une lésion bulleuse","q":"Comment définit-on une lésion bulleuse et comment la distingue-t-on des autres lésions liquidiennes ?","a":"<p>Une bulle est un <strong>soulèvement liquidien de la peau ou des muqueuses</strong> d'un diamètre <strong>supérieur à 5 mm</strong>. Son contenu peut être clair ou sérohématique. Elle se distingue des autres lésions liquidiennes par sa taille (la vésicule est plus petite, &lt; 5mm) et par la nature de son contenu (la pustule contient du pus).</p>"},{"i":"98e05cbc76f7","n":112,"o":"112-6","u":"Contenu multimédia","t":"Reconnaître une lésion bulleuse","q":"Quelles sont les principales étiologies des dermatoses bulleuses à connaître à l'EDN, par rapport à l'item 112 ?","a":"<ul><li><strong>Pemphigus</strong> (notamment le pemphigus vulgaire).</li><li><strong>Nécrolyse épidermique toxique</strong> (Syndrome de Stevens-Johnson et Syndrome de Lyell).</li><li><strong>Épidermolyse staphylococcique aiguë (SSSS)</strong>.</li></ul>"},{"i":"c24c8f124dd3","n":112,"o":"112-6","u":"Contenu multimédia","t":"Reconnaître une lésion bulleuse","q":"Quelles lésions secondaires évocatrices peuvent être associées aux dermatoses bulleuses auto-immunes (DBAI) et quel est le signe clinique majeur à rechercher ?","a":"<ul><li>Les lésions secondaires évocatrices comprennent les <strong>érosions post-bulleuses arrondies</strong> (parfois croûteuses), un <strong>vaste décollement épidermique</strong> donnant un aspect de « linge mouillé sur la peau », ou des <strong>cocardes / cibles à centre vésico-bulleux</strong> (orientant vers un érythème polymorphe).</li><li>Le signe clinique majeur à rechercher est le <strong>signe de Nikolsky</strong> : un décollement cutané provoqué par un frottement appuyé sur peau saine, traduisant un <strong>décollement intra-épidermique (acantholyse)</strong>.</li></ul>"}]};